update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle au Havre et dans l''estuaire de la Seine","mecanisme":"La zone industrialo-portuaire havraise aligne des procédés continus, des terminaux qui ne ferment jamais et un air salin qui attaque les organes exposés. Nous travaillons sur ce qui tourne en permanence : pompes, moteurs, compresseurs, ventilateurs, convoyeurs de quai. Nos techniciens se déplacent partout en France, l''astreinte couvre les nuits et les week-ends.","cta":"Demander une intervention au Havre","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés compris."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus après entretien technique et comportemental, résultats d''évaluation partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"Une pompe de transfert se met en défaut pendant une opération de chargement. Le navire, lui, a une fenêtre d''accostage, et elle ne se reporte pas.","puces":[{"accroche":"L''estuaire fonctionne sans pause.","texte":"Raffinage, chimie, terminaux : votre arrêt se compte en heures de flux bloqué, pas en heures de main d''œuvre."},{"accroche":"Le sel use ce que l''atelier ne voit pas.","texte":"Corrosion des enveloppes, roulements exposés, armoires en extérieur : la dégradation avance entre deux visites."},{"accroche":"Vos machines tournantes décident de tout.","texte":"Une pompe, un compresseur ou un ventilateur à l''arrêt fige une unité entière."},{"accroche":"La coactivité portuaire ne se négocie pas.","texte":"Engins, chargements, circulation : l''intervention se cale dans un créneau, pas dans une bonne intention."},{"accroche":"Le préventif recule dès qu''un technicien manque.","texte":"Le correctif prend sa place, et le budget suit dans le mauvais sens."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Machines tournantes traitées en priorité","texte":"contrôle, alignement, équilibrage, remplacement d''organes, remise en état."},"benefice":"Vous arbitrez entre réparation et échange sur une mesure, pas sur une impression."},{"prestation":{"accroche":"Techniciens habilités pour les sites à procédés continus","texte":", consignation et permis de feu systématiques."},"benefice":"L''accueil sécurité de votre site valide l''intervenant au premier passage."},{"prestation":{"accroche":"Dépannage cadré","texte":"diagnostic, remise en service, compte rendu écrit, dès le premier appel."},"benefice":"Vous nous mettez à l''épreuve sur un cas réel avant d''engager une relation longue."},{"prestation":{"accroche":"Préventif calé sur l''exposition réelle","texte":"organes en extérieur contrôlés plus souvent que ceux d''atelier."},"benefice":"Le plan tient compte du sel et de l''humidité, pas seulement des heures de marche."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [soudure et chaudronnerie](/expertises/soudure/)."},"benefice":"Un défaut qui mélange trois métiers mobilise une seule équipe."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Une panne de nuit ne devient pas une journée d''exploitation perdue."}],"prose":[{"texte":"Terminaux, entrepôts et plateformes de la vallée de la Seine relèvent de la [maintenance des équipements logistiques](/secteurs/logistique/) : convoyage, tri, quais, manutention."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, symptôme, criticité, accès au site, photos si vous en avez. Chaque détail fait gagner du temps sur le diagnostic."},{"titre":"Nous vous rappelons dans l''heure","texte":"qualification du besoin, des habilitations exigées et des pièces à anticiper avant le départ."},{"titre":"Le devis précède le déplacement","texte":"périmètre, conditions de chantier, chiffrage. Aucun poste exceptionnel ne sort en fin de facture."},{"titre":"L''intervention respecte votre protocole","texte":"accueil sécurité, plan de prévention, consignation, puis diagnostic."},{"titre":"La cause racine est traitée après la remise en route","texte":"mesures, historique machine, conditions d''exploitation."},{"titre":"Le compte rendu part dans votre GMAO","texte":"constat, actions, pièces, organes à surveiller au prochain passage."}]},{"type":"garanties","puces":[{"accroche":"Vous savez qui entre sur le site","texte":"entretien technique et comportemental pour chaque candidat, 10 % retenus, résultats d''évaluation présentés avant l''arrivée du technicien."},{"accroche":"Aucun délai de route inventé","texte":"le rappel dans l''heure aux horaires ouvrés et l''astreinte 24/24 et 7/7 en option sont les seuls engagements de délai écrits. Le reste se cale sur votre implantation exacte."},{"accroche":"Des pièces consultées au prix du marché","texte":"composants d''origine ou équivalents, sans coefficient caché, avec l''arbitrage qui vous revient."}]},{"type":"cta","question":"Besoin d''un avis technique sur une machine tournante qui fatigue ?","bouton":"Demander une intervention au Havre","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un électromécanicien habilité risque chimique RC1, mobilisé six mois pour la remise en état d''un site de traitement des eaux industrielles","texte":"un environnement où l''accès se mérite","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Six techniciens engagés sur l''installation et la mise en production d''un nouveau parc machine","texte":"démarrage d''un site automobile, à partir de janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Un technicien polyvalent intégré pour tenir un parc machines hétérogène en forte cadence","texte":"papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Deux techniciens en poste sur site, dédiés à la maintenance curative des convoyeurs, trieurs et packaging","texte":"logistique et transport","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Un responsable maintenance intégré sur site pendant une montée de cadence","texte":"pilotage repris sans interruption de service, troisième trimestre 2025","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment au Havre, alors que votre siège est à Lyon ?","reponse":"Oui, et nous ne publions pas d''adresse locale inventée. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nos techniciens se déplacent partout en France, avec les renforts du groupe quand la panne sort du cadre. Votre demande est rappelée dans l''heure aux horaires ouvrés. Le jour de l''intervention, ce qui change quelque chose, c''est le niveau du technicien et son outillage."},{"question":"Jusqu''où va votre couverture autour du Havre ?","reponse":"Le Havre, Gonfreville-l''Orcher, Harfleur, Montivilliers, Sainte-Adresse et la zone industrialo-portuaire. Puis la vallée de la Seine vers Bolbec et Lillebonne, jusqu''à Rouen et Honfleur. Au-delà, le réseau national prend le relais."},{"question":"Prenez-vous en charge les machines tournantes ?","reponse":"Oui, c''est l''un de nos terrains les plus fréquents. Pompes, moteurs, compresseurs, ventilateurs, réducteurs : contrôle, alignement, équilibrage, usinage de reprise, remise en état en atelier ou sur site. L''étude chiffrée compare réparation et échange, vous décidez."},{"question":"Pouvez-vous intervenir pendant une opération portuaire ?","reponse":"Oui, avec un créneau convenu et un plan de prévention écrit. Les opérations lourdes se planifient hors mouvement, les contrôles et une part du préventif se réalisent en marche sur les équipements qui le permettent."},{"question":"Comment reprenez-vous un parc sans documentation ?","reponse":"Nous reconstruisons l''essentiel : inventaire, criticité, historique de pannes, puis un plan d''entretien réaliste versé dans votre GMAO. Le cas revient souvent après un départ dans l''équipe maintenance."},{"question":"Que couvre le contrat Zéro arrêt ?","reponse":"Préventif planifié, priorité en cas de panne, astreinte en option, sur devis, engagement type 6 mois renouvelable. Le périmètre du [contrat de maintenance](/offres/zero-arret/) s''écrit équipement par équipement après un diagnostic gratuit."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser vos machines tournantes avant le prochain pic d''activité ?","bouton":"Demander une intervention au Havre","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-le-havre/';
